        let ev = h.take_events();
        assert!(!ev.is_empty() && ev.iter().all(|x| *x == (e, "notify::spinning".to_string())), "delivered: {ev:?}");
        h.listen(e, "notify::spinning", false).unwrap();
        fire(&h.obj(e), "False", 1);
